import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.B9unkguw.js";const p=JSON.parse(`{"title":"What's New","description":"","frontmatter":{},"headers":[],"relativePath":"ko/qgc-user-guide/getting_started/whats_new.md","filePath":"ko/qgc-user-guide/getting_started/whats_new.md"}`),n={name:"ko/qgc-user-guide/getting_started/whats_new.md"};function r(s,e,l,d,c,h){return t(),i("div",null,e[0]||(e[0]=[o('<h1 id="what-s-new" tabindex="-1">What&#39;s New <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s New&quot;">​</a></h1><p>This page highlights user-facing changes since the last stable release (V5.1).</p><h2 id="fly-view" tabindex="-1">Fly View <a class="header-anchor" href="#fly-view" aria-label="Permalink to &quot;Fly View&quot;">​</a></h2><h3 id="toolbar-indicator-improvements" tabindex="-1">Toolbar Indicator Improvements <a class="header-anchor" href="#toolbar-indicator-improvements" aria-label="Permalink to &quot;Toolbar Indicator Improvements&quot;">​</a></h3><ul><li><strong>Flight Modes</strong> — mode changes now require a hold to confirm, and VTOL transition is handled from the indicator.</li><li><strong>GPS Resilience</strong> — new indicator appears when the vehicle reports GPS spoofing or jamming state, with per-GPS details in the dropdown.</li><li><strong>ESC Status</strong> — new indicator showing ESC telemetry.</li><li><strong>Gimbal</strong> — reworked to match the new indicator UI style.</li><li><strong>MAVLink Signing</strong> — new indicator shows whether MAVLink 2 message signing is active on the current vehicle connection, with named key management in Application Settings and per-vehicle key auto-detection.</li><li><strong>Remote ID</strong> — live status (status flags, GCS position) now lives solely in the indicator&#39;s expanded page, while the Remote ID page in Application Settings contains only settings.</li></ul><h3 id="camera-ui-rework" tabindex="-1">Camera UI Rework <a class="header-anchor" href="#camera-ui-rework" aria-label="Permalink to &quot;Camera UI Rework&quot;">​</a></h3><p>The camera management code and UI have been significantly reworked. The camera UI now correctly respects camera capability flags and modes, and behavior is more consistent across different camera types and configurations.</p><h3 id="vehicle-actions" tabindex="-1">Vehicle Actions <a class="header-anchor" href="#vehicle-actions" aria-label="Permalink to &quot;Vehicle Actions&quot;">​</a></h3><p>Better support for Go To Location, Orbit, and Fixed Wing Loiter actions.</p><h3 id="multi-vehicle" tabindex="-1">Multi-Vehicle <a class="header-anchor" href="#multi-vehicle" aria-label="Permalink to &quot;Multi-Vehicle&quot;">​</a></h3><p>Multi-vehicle support improvements: configurable telemetry display and better support for applying actions to all vehicles.</p><h3 id="_3d-view-camera-controls" tabindex="-1">3D View Camera Controls <a class="header-anchor" href="#_3d-view-camera-controls" aria-label="Permalink to &quot;3D View Camera Controls&quot;">​</a></h3><p>The 3D View free-fly camera has been replaced with Gazebo-style cursor-anchored controls — the ground point you grab stays under the cursor while you pan, orbit, and zoom. Full mouse and touch gesture support is included, along with a scale bar showing ground distance.</p><h2 id="plan-view" tabindex="-1">Plan View <a class="header-anchor" href="#plan-view" aria-label="Permalink to &quot;Plan View&quot;">​</a></h2><h3 id="unified-plan-tree" tabindex="-1">Unified Plan Tree <a class="header-anchor" href="#unified-plan-tree" aria-label="Permalink to &quot;Unified Plan Tree&quot;">​</a></h3><p>The right panel is now a single unified tree view of the entire plan, replacing the separate mission item list and GeoFence/Rally editors:</p><ul><li><strong>Plan Info</strong>, <strong>Defaults</strong>, <strong>Mission</strong>, <strong>GeoFence</strong>, and <strong>Rally Points</strong> are shown as collapsible sections in one tree.</li><li>Expanding the Mission, GeoFence, or Rally section makes it the active map editing layer — the sections are exclusive, so it is always clear which layer map clicks affect.</li><li>Mission items are edited inline in the tree, including mission transforms.</li><li>The tree automatically expands and scrolls to newly added or selected items, and the whole panel can be collapsed to maximize map space.</li></ul><h3 id="toolbar-rework" tabindex="-1">Toolbar Rework <a class="header-anchor" href="#toolbar-rework" aria-label="Permalink to &quot;Toolbar Rework&quot;">​</a></h3><p>The Plan View toolbar has been completely reworked:</p><ul><li>Explicit <strong>Open</strong>, <strong>Save</strong>, <strong>Upload</strong>, and <strong>Clear</strong> buttons replace the old File tool button.</li><li>Vehicle upload and storage status are shown directly in the toolbar.</li><li><strong>Save</strong> and <strong>Upload</strong> buttons are highlighted when there are unsaved or un-uploaded changes.</li><li>A hamburger menu (☰) provides additional options such as Save as KML and Download from vehicle.</li><li>Plan creation from a template has moved to the right panel and is shown only when the plan is empty.</li></ul><h3 id="mission-status-panel" tabindex="-1">Mission Status Panel <a class="header-anchor" href="#mission-status-panel" aria-label="Permalink to &quot;Mission Status Panel&quot;">​</a></h3><p>A new collapsible <strong>Mission Status</strong> panel at the bottom of the Plan View shows terrain profile and mission statistics (distance, time, maximum altitude). Switchable sub-panels let you toggle between terrain data and mission stats.</p><h3 id="click-to-set-home-position" tabindex="-1">Click-to-Set Home Position <a class="header-anchor" href="#click-to-set-home-position" aria-label="Permalink to &quot;Click-to-Set Home Position&quot;">​</a></h3><p>The home position in Plan View is now set by an explicit first click on the map rather than tracking the map center. Mission editing tools (Takeoff, Waypoint, Pattern, Land, ROI) are disabled until the home position is placed, preventing accidentally placing items before the reference point is defined.</p><h3 id="plan-templates-with-vehicle-class-filtering" tabindex="-1">Plan Templates with Vehicle Class Filtering <a class="header-anchor" href="#plan-templates-with-vehicle-class-filtering" aria-label="Permalink to &quot;Plan Templates with Vehicle Class Filtering&quot;">​</a></h3><p>The Plan Creator now filters available plan templates by vehicle class (multirotor, fixed wing, VTOL, rover, sub), showing only templates compatible with the connected or configured vehicle.</p><h2 id="analyze-view" tabindex="-1">Analyze View <a class="header-anchor" href="#analyze-view" aria-label="Permalink to &quot;Analyze View&quot;">​</a></h2><h3 id="log-viewer" tabindex="-1">Log Viewer <a class="header-anchor" href="#log-viewer" aria-label="Permalink to &quot;Log Viewer&quot;">​</a></h3><p>The Log Viewer is a new unified post-flight analysis tool that supports three log formats:</p><ul><li><strong>ArduPilot DataFlash</strong> (<code>.bin</code> / <code>.log</code>) — field charting, GPS flight path map, parameter inspection, and status messages.</li><li><strong>PX4 ULog</strong> (<code>.ulg</code>) — same capabilities using PX4 log format.</li><li><strong>MAVLink Telemetry</strong> (<code>.tlog</code>) — playback with speed control, seek slider, and live MAVLink Inspector.</li></ul><p>The Charting tab lets you select any logged field for time-series plotting:</p><ul><li>Multiple fields plotted at once with a color-coded legend and per-field min/max/current values.</li><li>Click or drag on the chart to place a cursor with a popup showing exact values at that time.</li><li>Flight mode and event markers can be overlaid on the chart.</li><li>Zoom into any time range; the X axis can show elapsed time or local clock time.</li></ul><p>The Map tab shows the GPS flight path auto-fitted to the screen with an altitude mini-chart below it; clicking or dragging on the altitude chart moves a position marker on the map. The Parameters tab lists all recorded parameters with a &quot;changed only&quot; filter.</p><h3 id="onboard-logs" tabindex="-1">Onboard Logs <a class="header-anchor" href="#onboard-logs" aria-label="Permalink to &quot;Onboard Logs&quot;">​</a></h3><p>Downloading logs from the vehicle now automatically uses the best available transport: MAVLink FTP when the vehicle supports it, falling back to the legacy log transfer messages otherwise. FTP transfers also allow deleting individual logs from the vehicle.</p><h3 id="mavlink-inspector" tabindex="-1">MAVLink Inspector <a class="header-anchor" href="#mavlink-inspector" aria-label="Permalink to &quot;MAVLink Inspector&quot;">​</a></h3><ul><li>Messages are now separated by instance (e.g. <code>sensor_id</code>), so multiple sensors of the same type can be inspected individually.</li><li>Numeric array fields expand into individual elements that can be charted separately.</li><li><code>NAMED_VALUE_*</code> and <code>DEBUG*</code> messages are separated by name for easier debugging.</li><li>Charting improvements with more efficient data handling.</li></ul><h2 id="vehicle-configuration" tabindex="-1">Vehicle Configuration <a class="header-anchor" href="#vehicle-configuration" aria-label="Permalink to &quot;Vehicle Configuration&quot;">​</a></h2><p>Vehicle Configuration has been renamed from Vehicle Setup and is now intended mainly for initial vehicle design and configuration, not changes between flights. Settings you may want to adjust from one flight to the next are instead available from the expanded pages of the toolbar indicators in Fly View.</p><ul><li>The sidebar is now a tree: each page expands to show the sections within it, and clicking a section jumps directly to it on the page.</li><li>A new <strong>keyword search</strong> field filters the tree to matching pages and sections, making it much faster to find a specific setting.</li></ul><h3 id="parameter-editor" tabindex="-1">Parameter Editor <a class="header-anchor" href="#parameter-editor" aria-label="Permalink to &quot;Parameter Editor&quot;">​</a></h3><h4 id="tabbed-views-and-favorites" tabindex="-1">Tabbed Views and Favorites <a class="header-anchor" href="#tabbed-views-and-favorites" aria-label="Permalink to &quot;Tabbed Views and Favorites&quot;">​</a></h4><p>The Parameter Editor now provides <strong>Full List</strong>, <strong>Modified</strong>, and <strong>Favorites</strong> tabs, replacing the old &quot;Show modified only&quot; checkbox. Mark frequently used parameters as favorites via the new Fav column; favorites persist across sessions.</p><h4 id="read-only-parameters" tabindex="-1">Read-Only Parameters <a class="header-anchor" href="#read-only-parameters" aria-label="Permalink to &quot;Read-Only Parameters&quot;">​</a></h4><p>Parameters flagged as read-only by the vehicle are now shown as such in the UI and cannot be edited by default. Advanced-UI users can deliberately override the lock via a <strong>Force edit read-only param</strong> checkbox for diagnostic and recovery cases.</p><h4 id="mission-planner-file-import" tabindex="-1">Mission Planner File Import <a class="header-anchor" href="#mission-planner-file-import" aria-label="Permalink to &quot;Mission Planner File Import&quot;">​</a></h4><p>The parameter diff dialog can now load Mission Planner <code>.param</code> files (whitespace-separated 5-column format) in addition to the existing QGC <code>.params</code> format. Select a <code>.param</code> file using the new <strong>Mission Planner Files (*.param)</strong> filter in the load dialog; differences from the vehicle&#39;s current values are shown as usual before any changes are applied.</p><h3 id="joystick" tabindex="-1">Joystick <a class="header-anchor" href="#joystick" aria-label="Permalink to &quot;Joystick&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Joystick settings from earlier versions are not migrated; joysticks will need to be re-calibrated and re-enabled after updating.</p></div><h4 id="manual-control-extensions" tabindex="-1">Manual Control Extensions <a class="header-anchor" href="#manual-control-extensions" aria-label="Permalink to &quot;Manual Control Extensions&quot;">​</a></h4><p>Full support for MAVLink manual control extensions has been added to the Joystick configuration:</p><ul><li>Improved settings read/write with validation.</li><li>Improved logging.</li></ul><h4 id="additional-stick-axes" tabindex="-1">Additional Stick Axes <a class="header-anchor" href="#additional-stick-axes" aria-label="Permalink to &quot;Additional Stick Axes&quot;">​</a></h4><p>Up to 8 additional joystick axes can now be sent to the vehicle via MAVLink <code>RC_CHANNELS_OVERRIDE</code> extension channels (19–26), with a full calibration and settings workflow.</p><h4 id="camera-focus-actions" tabindex="-1">Camera Focus Actions <a class="header-anchor" href="#camera-focus-actions" aria-label="Permalink to &quot;Camera Focus Actions&quot;">​</a></h4><p>Joystick buttons can now be bound to <strong>Step Focus In/Out</strong> and <strong>Continuous Focus In/Out</strong> camera actions (for cameras that report basic focus support).</p><h3 id="ardupilot" tabindex="-1">ArduPilot <a class="header-anchor" href="#ardupilot" aria-label="Permalink to &quot;ArduPilot&quot;">​</a></h3><h4 id="servo-outputs" tabindex="-1">Servo Outputs <a class="header-anchor" href="#servo-outputs" aria-label="Permalink to &quot;Servo Outputs&quot;">​</a></h4><p>A new <strong>Servo Outputs</strong> page provides real-time visualization and configuration of servo outputs:</p><ul><li>Live PWM output bars updated in real time.</li><li>Per-channel function assignment, direction reversal, and min/max/trim PWM editing.</li></ul><h4 id="scripting" tabindex="-1">Scripting <a class="header-anchor" href="#scripting" aria-label="Permalink to &quot;Scripting&quot;">​</a></h4><p>A new <strong>Scripting</strong> page lets you manage Lua scripts on the vehicle directly from QGroundControl:</p><ul><li>Browse, upload, and delete scripts stored on the vehicle via MAVLink FTP.</li><li>No need for a separate file manager or SD card access.</li></ul><h4 id="safety-failsafe-modernization" tabindex="-1">Safety Failsafe Modernization <a class="header-anchor" href="#safety-failsafe-modernization" aria-label="Permalink to &quot;Safety Failsafe Modernization&quot;">​</a></h4><p>The Safety setup page has been modernized with vehicle-specific failsafe sections for Copter, Plane, and Rover. Controls use consistent slider and radio-button patterns, and a new bitmask checkbox control makes bitmask parameters much easier to configure.</p><h4 id="esc-configuration" tabindex="-1">ESC Configuration <a class="header-anchor" href="#esc-configuration" aria-label="Permalink to &quot;ESC Configuration&quot;">​</a></h4><p>ESC configuration and calibration have been extracted from the Power page into a new standalone <strong>ESC</strong> setup page, with support for both <code>MOT_*</code> (Copter/Rover/Sub) and <code>Q_M_*</code> (QuadPlane) parameter prefixes. The Power page now uses tabs to switch between Battery 1 and Battery 2.</p><h4 id="airspeed" tabindex="-1">Airspeed <a class="header-anchor" href="#airspeed" aria-label="Permalink to &quot;Airspeed&quot;">​</a></h4><p>A new <strong>Airspeed</strong> setup page provides Basic/Advanced tabbed configuration of airspeed sensors:</p><ul><li><strong>Basic</strong>: sensor type, use airspeed, ratio, auto-calibrate, primary sensor selection, and airspeed limits.</li><li><strong>Advanced</strong>: per-sensor offset, pitot tube order, analog pin, I2C bus, PSI range, health monitoring, and options bitmask.</li></ul><h4 id="logging-configuration" tabindex="-1">Logging Configuration <a class="header-anchor" href="#logging-configuration" aria-label="Permalink to &quot;Logging Configuration&quot;">​</a></h4><p>A new <strong>Logging</strong> page lets you configure logging parameters directly from QGroundControl, including storage backends (<code>LOG_BACKEND_TYPE</code>), data group bitmasks (<code>LOG_BITMASK</code>), rate limits, and disarmed logging options.</p><h4 id="configurable-stream-rates" tabindex="-1">Configurable Stream Rates <a class="header-anchor" href="#configurable-stream-rates" aria-label="Permalink to &quot;Configurable Stream Rates&quot;">​</a></h4><p>Configurable telemetry stream rate support for ArduPilot vehicles.</p><h2 id="application-settings" tabindex="-1">Application Settings <a class="header-anchor" href="#application-settings" aria-label="Permalink to &quot;Application Settings&quot;">​</a></h2><ul><li>The sidebar is now a tree: each page expands to show the sections within it, and clicking a section jumps directly to it on the page.</li><li>A new <strong>keyword search</strong> field filters the tree to matching pages and sections across all pages, making it much faster to find a specific setting without knowing which page it lives on.</li></ul><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><h4 id="audio-mute" tabindex="-1">Audio Mute <a class="header-anchor" href="#audio-mute" aria-label="Permalink to &quot;Audio Mute&quot;">​</a></h4><p>Muting audio output no longer zeroes out the volume slider — mute is now a separate setting, so your preferred volume level is preserved when unmuting.</p><h3 id="fly-view-1" tabindex="-1">Fly View <a class="header-anchor" href="#fly-view-1" aria-label="Permalink to &quot;Fly View&quot;">​</a></h3><h4 id="virtual-joystick" tabindex="-1">Virtual Joystick <a class="header-anchor" href="#virtual-joystick" aria-label="Permalink to &quot;Virtual Joystick&quot;">​</a></h4><p>Virtual Joystick now supports left-handed mode.</p><h3 id="plan-view-1" tabindex="-1">Plan View <a class="header-anchor" href="#plan-view-1" aria-label="Permalink to &quot;Plan View&quot;">​</a></h3><h4 id="multiple-fixed-wing-landing-sequences" tabindex="-1">Multiple Fixed Wing Landing Sequences <a class="header-anchor" href="#multiple-fixed-wing-landing-sequences" aria-label="Permalink to &quot;Multiple Fixed Wing Landing Sequences&quot;">​</a></h4><p>A new <strong>Allow configuring multiple landing sequences</strong> setting enables planning fixed wing landing sequences at different locations, allowing Return-to-Launch contingency selection.</p><h3 id="comm-links" tabindex="-1">Comm Links <a class="header-anchor" href="#comm-links" aria-label="Permalink to &quot;Comm Links&quot;">​</a></h3><h4 id="custom-serial-baud-rates" tabindex="-1">Custom Serial Baud Rates <a class="header-anchor" href="#custom-serial-baud-rates" aria-label="Permalink to &quot;Custom Serial Baud Rates&quot;">​</a></h4><p>Serial link and NMEA GPS baud rate selectors now include a <strong>Custom</strong> option with a numeric text field for entering arbitrary baud rates.</p><h3 id="ntrip-rtk" tabindex="-1">NTRIP/RTK <a class="header-anchor" href="#ntrip-rtk" aria-label="Permalink to &quot;NTRIP/RTK&quot;">​</a></h3><h4 id="built-in-ntrip-client" tabindex="-1">Built-In NTRIP Client <a class="header-anchor" href="#built-in-ntrip-client" aria-label="Permalink to &quot;Built-In NTRIP Client&quot;">​</a></h4><p>QGroundControl now includes a built-in NTRIP client for streaming RTK correction data to the vehicle. Configure the NTRIP server, mount point, and credentials; QGroundControl connects and forwards corrections automatically.</p><h3 id="telemetry" tabindex="-1">Telemetry <a class="header-anchor" href="#telemetry" aria-label="Permalink to &quot;Telemetry&quot;">​</a></h3><h4 id="connecting-to-a-flying-vehicle" tabindex="-1">Connecting to a Flying Vehicle <a class="header-anchor" href="#connecting-to-a-flying-vehicle" aria-label="Permalink to &quot;Connecting to a Flying Vehicle&quot;">​</a></h4><p>A new <strong>Skip initial download when flying</strong> setting skips parameter and mission plan downloads when connecting to a vehicle that is already armed, preventing bandwidth saturation on constrained links. Toolbar indicators show a compact view immediately, and Vehicle Configuration offers a manual <strong>Download Parameters</strong> button when needed.</p><h2 id="general-1" tabindex="-1">General <a class="header-anchor" href="#general-1" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="android-improvements" tabindex="-1">Android Improvements <a class="header-anchor" href="#android-improvements" aria-label="Permalink to &quot;Android Improvements&quot;">​</a></h3><ul><li>On Android 11+, application data (logs, plans, settings) is now saved to the root of a removable SD card when one is present, using the &quot;All files access&quot; permission.</li><li>A new POSIX serial backend (selectable via an app setting) adds support for built-in serial ports (<code>/dev/ttyS*</code>, <code>/dev/ttyHS*</code>) on integrated controllers, in addition to USB serial devices.</li></ul><h3 id="mavlink-v1-removed" tabindex="-1">MAVLink v1 Removed <a class="header-anchor" href="#mavlink-v1-removed" aria-label="Permalink to &quot;MAVLink v1 Removed&quot;">​</a></h3><p>Support for the legacy MAVLink v1 message protocol has been removed. QGroundControl now requires MAVLink v2.</p><h2 id="developer" tabindex="-1">Developer <a class="header-anchor" href="#developer" aria-label="Permalink to &quot;Developer&quot;">​</a></h2><h3 id="json-driven-settings-ui" tabindex="-1">JSON-Driven Settings UI <a class="header-anchor" href="#json-driven-settings-ui" aria-label="Permalink to &quot;JSON-Driven Settings UI&quot;">​</a></h3><p>Application Settings pages and many Vehicle Configuration pages are now generated from JSON metadata rather than hand-coded QML. Settings are organized into collapsible sections with consistent layout.</p><h3 id="settings-override-files" tabindex="-1">Settings Override Files <a class="header-anchor" href="#settings-override-files" aria-label="Permalink to &quot;Settings Override Files&quot;">​</a></h3><p>Application settings can now be overridden — changing defaults, forcing values, hiding settings from the UI — without a custom build. See <a href="./../../qgc-dev-guide/file_formats/settings_override.html">Settings Override Files</a> for details.</p><h3 id="qt-framework-update" tabindex="-1">Qt Framework Update <a class="header-anchor" href="#qt-framework-update" aria-label="Permalink to &quot;Qt Framework Update&quot;">​</a></h3><p>The Qt framework has been updated from 6.8.3 to 6.10.1, and the charting library has been migrated from the deprecated Qt Charts to the new Qt Graphs module.</p><h3 id="build-system" tabindex="-1">Build System <a class="header-anchor" href="#build-system" aria-label="Permalink to &quot;Build System&quot;">​</a></h3><p>The build system has been fully converted to CMake (qmake is no longer supported). GStreamer support updated to 1.22.</p><h3 id="api-documentation" tabindex="-1">API Documentation <a class="header-anchor" href="#api-documentation" aria-label="Permalink to &quot;API Documentation&quot;">​</a></h3><p>Doxygen-generated API documentation is now built and published automatically by a weekly CI pipeline, available at <a href="https://api.qgroundcontrol.com/master/annotated.html" target="_blank" rel="noreferrer">https://api.qgroundcontrol.com/master/annotated.html</a>.</p>',110)]))}const g=a(n,[["render",r]]);export{p as __pageData,g as default};
